<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';if(!v700_module_enabled('education')){http_response_code(404);exit('Education disabled.');}$u=v700_require_user();$uid=(int)$u['id'];$programId=(int)($_GET['program']??$_POST['program_id']??0);$institutionId=(int)($_GET['institution']??$_POST['institution_id']??0);if($programId){$p=v700_one('edu_programs_v700',$programId,"status='active'");if($p)$institutionId=(int)$p['institution_id'];}else{$p=null;}$inst=$institutionId?v700_one('edu_institutions_v700',$institutionId,"status='active'"):null;$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$id=v700_create_education_application($uid,$_POST);$flash='Application submitted successfully. Reference #'.$id;}}catch(Throwable $e){$err=$e->getMessage();}$institutions=v700_rows("SELECT id,name FROM edu_institutions_v700 WHERE tenant_id=? AND status='active' ORDER BY name",[v700_tid()]);v700_public_header('Apply for Admission','Submit an education application online.','education');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">ONLINE ADMISSION</span><h1>Apply to <?=e($inst['name']??'an institution')?></h1><p>Your application will be visible only to the relevant tenant education staff and institution managers.</p></div></section><section class="v700-section soft"><div class="v700-shell" style="max-width:820px"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><form method="post" class="v700-panel v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Institution<select name="institution_id" required><?php foreach($institutions as $x):?><option value="<?=(int)$x['id']?>" <?=((int)$x['id']===$institutionId)?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Program ID (optional)<input type="number" name="program_id" value="<?=$programId?:''?>"></label><div class="two"><label>Applicant Name<input name="applicant_name" required value="<?=e($u['name']??'')?>"></label><label>Phone<input name="phone" required value="<?=e($u['phone']??'')?>"></label></div><label>Email<input type="email" name="email" value="<?=e($u['email']??'')?>"></label><label>Previous Qualification<input name="previous_qualification"></label><label>Message<textarea name="message" rows="5" placeholder="Tell the institution about your admission interest."></textarea></label><button class="v700-btn primary">Submit Application</button></form></div></section></main><?php v700_public_footer(); ?>
